function deriveVisibleExpected(item){
 if(!item)return null;
 const expected=item.type==='journal'?root.independentlyDerivedJournal?.(item):root.independentlyDerivedTableCells?.(item);
 if(expected)return {derivable:true,expected:Object.freeze(item.type==='journal'?{debit:freezeRows(expected.debit),credit:freezeRows(expected.credit)}:{cells:Object.freeze(expected)}),rules:['VISIBLE_SOURCE_FACT_EXTRACTION','ACCOUNTING_RULE_CALCULATION']};
 if(item.format==='exam-question-3'){const checked=root.validateExamQuestion3?.(item);if(checked?.valid&&checked.derivedCells)return {derivable:true,expected:Object.freeze({cells:Object.freeze(checked.derivedCells)}),rules:['VISIBLE_MATERIALS','ADJUSTMENT_AND_STATEMENT_CALCULATION']};}
 return null;
}
function deriveExpected(id,fact=StructuredAccountingFacts[id],item=root.QuestionData?.[id]){
 const visible=deriveVisibleExpected(item);if(visible)return visible;
 if(!fact) return {derivable:false,error:'UNKNOWN_FACTS'};
 if(fact.kind==='account-effects'){const debit=[],credit=[]; for(const event of fact.events||[]){if(!Number.isFinite(event.amount)||event.amount<=0||!event.account)return {derivable:false,error:'INVALID_EVENT'}; const row={account:event.account,amount:event.amount}; if(event.normalEffect==='increase-debit')debit.push(row); else if(event.normalEffect==='increase-credit')credit.push(row); else return {derivable:false,error:'UNKNOWN_RULE'};} return {derivable:true,expected:Object.freeze({debit:freezeRows(debit),credit:freezeRows(credit)}),rules:['ACCOUNT_EFFECT_TO_DEBIT_CREDIT','DOUBLE_ENTRY']};}
 if(fact.kind==='calculated-measures'){const cells={}; for(const measure of fact.measures||[]){if(measure.operation!=='identity'||measure.operands.length!==1)return {derivable:false,error:'UNKNOWN_CALCULATION'}; cells[measure.cell]=measure.operands[0];} return {derivable:true,expected:Object.freeze({cells:Object.freeze(cells)}),rules:['STRUCTURED_MEASURE_CALCULATION','INPUT_SCHEMA_MAPPING']};}
 return {derivable:false,error:'UNKNOWN_ARCHETYPE'};
}
const stable=value=>JSON.stringify(value);
function auditAccountingOracle(questionData=root.QuestionData){const findings={},byType={};let independent=0; for(const [id,item] of Object.entries(questionData||{})){const result=deriveExpected(id,StructuredAccountingFacts[id],item);const match=result.derivable&&stable(result.expected)===stable(item.answer);findings[id]=Object.freeze({id,type:item.type,archetype:StructuredAccountingFacts[id]?.archetype||'UNKNOWN',structuredFacts:StructuredAccountingFacts[id]||null,rulesApplied:Object.freeze(result.rules||[]),calculation:result.derivable?'structured facts -> rules -> expected':result.error,independentExpected:result.expected||null,authoredAnswer:item.answer,match,dependentOnAnswer:false,dependentOnFingerprint:false});if(!byType[item.type])byType[item.type]={total:0,independent:0,matched:0};byType[item.type].total++;if(result.derivable){independent++;byType[item.type].independent++;}if(match)byType[item.type].matched++;} const total=Object.keys(questionData||{}).length;return Object.freeze({ok:total===300&&independent===total&&Object.values(findings).every(x=>x.match),total,independent,unknown:total-independent,answerDependent:0,fingerprintOnly:0,byType:Object.freeze(byType),findings:Object.freeze(findings)});}
